      if (t >= TL.ray[1] && t < TL.fall[0] + .1) drawSun(t, S);   // à l'aube, le soleil naît au point d'impact, derrière les crêtes
      drawRidges(t);
      drawRay(t);
      if (t > TL.impact - .05 && t < TL.logo + .6) { drawFlashes(t); drawImpact(t); drawDots(t); drawNet(t); drawBadges(t); }
      if (t >= TL.fall[0] + .1) drawSun(t, S);
